"use strict";(globalThis.webpackChunkmy_website||=[]).push([[70306],{24239(e){e.exports=JSON.parse('{"slug":"nakamoto-coefficient","title":"Nakamoto Coefficient","short":"A measure of how decentralized a blockchain is, expressed as the smallest number of entities that could collude to compromise it.","category":"general","aliases":[],"mentalModel":null,"related":["edinburgh-decentralisation-index-edi","proof-of-stake","stake-pool"],"sources":[],"link":null,"level":"advanced","body":"A simple yardstick for measuring how decentralized a blockchain is: the smallest number of independent entities that would need to collude to disrupt the network. The higher the Nakamoto Coefficient, the more parties an attacker would have to coordinate.\\n\\nFor proof-of-stake systems the coefficient is typically computed across stake pools, validators, or block producers; for proof-of-work it is computed across mining pools. Either way, a single low number signals concentration risk."}')}}]);